import os
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, field_validator
from openai import OpenAI


class ConfidenceScore(BaseModel):
    value: float = Field(..., ge=0.0, le=1.0)


class ExtractedField(BaseModel):
    value: str = Field(..., min_length=1)
    confidence: ConfidenceScore


class DocumentExtraction(BaseModel):
    invoice_number: ExtractedField
    invoice_date: ExtractedField
    vendor_name: ExtractedField
    total_amount: ExtractedField
    currency: ExtractedField

    @field_validator(
        "invoice_number",
        "invoice_date",
        "vendor_name",
        "total_amount",
        "currency",
        mode="before",
    )
    @classmethod
    def validate_required_field(cls, v: Any) -> Any:
        if v is None:
            raise ValueError("required field is missing")
        return v


def extract_structured_document(
    document_text: str,
    model: str = "gpt-4o-mini",
) -> Dict[str, Any]:
    client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

    schema = {
        "type": "json_schema",
        "json_schema": {
            "name": "document_extraction",
            "strict": True,
            "schema": {
                "type": "object",
                "additionalProperties": False,
                "required": [
                    "invoice_number",
                    "invoice_date",
                    "vendor_name",
                    "total_amount",
                    "currency",
                ],
                "properties": {
                    "invoice_number": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["value", "confidence"],
                        "properties": {
                            "value": {"type": "string", "minLength": 1},
                            "confidence": {
                                "type": "object",
                                "additionalProperties": False,
                                "required": ["value"],
                                "properties": {
                                    "value": {"type": "number", "minimum": 0, "maximum": 1}
                                },
                            },
                        },
                    },
                    "invoice_date": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["value", "confidence"],
                        "properties": {
                            "value": {"type": "string", "minLength": 1},
                            "confidence": {
                                "type": "object",
                                "additionalProperties": False,
                                "required": ["value"],
                                "properties": {
                                    "value": {"type": "number", "minimum": 0, "maximum": 1}
                                },
                            },
                        },
                    },
                    "vendor_name": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["value", "confidence"],
                        "properties": {
                            "value": {"type": "string", "minLength": 1},
                            "confidence": {
                                "type": "object",
                                "additionalProperties": False,
                                "required": ["value"],
                                "properties": {
                                    "value": {"type": "number", "minimum": 0, "maximum": 1}
                                },
                            },
                        },
                    },
                    "total_amount": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["value", "confidence"],
                        "properties": {
                            "value": {"type": "string", "minLength": 1},
                            "confidence": {
                                "type": "object",
                                "additionalProperties": False,
                                "required": ["value"],
                                "properties": {
                                    "value": {"type": "number", "minimum": 0, "maximum": 1}
                                },
                            },
                        },
                    },
                    "currency": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["value", "confidence"],
                        "properties": {
                            "value": {"type": "string", "minLength": 1},
                            "confidence": {
                                "type": "object",
                                "additionalProperties": False,
                                "required": ["value"],
                                "properties": {
                                    "value": {"type": "number", "minimum": 0, "maximum": 1}
                                },
                            },
                        },
                    },
                },
            },
        },
    }

    response = client.responses.create(
        model=model,
        input=[
            {
                "role": "system",
                "content": (
                    "Extract structured invoice fields from the provided document text. "
                    "Return all required fields. For each field, include a value and a confidence "
                    "score between 0 and 1. If uncertain, still provide your best extraction."
                ),
            },
            {
                "role": "user",
                "content": document_text,
            },
        ],
        text={"format": schema},
    )

    parsed = getattr(response, "output_parsed", None)
    if parsed is None:
        if not getattr(response, "output_text", None):
            raise ValueError("No structured output returned by OpenAI Responses API")
        import json

        parsed = json.loads(response.output_text)

    try:
        validated = DocumentExtraction.model_validate(parsed)
    except ValidationError as e:
        raise ValueError(f"Structured extraction validation failed: {e}") from e

    result = validated.model_dump()

    for field_name in [
        "invoice_number",
        "invoice_date",
        "vendor_name",
        "total_amount",
        "currency",
    ]:
        conf = result[field_name]["confidence"]["value"]
        if not (0.0 <= conf <= 1.0):
            raise ValueError(f"Confidence for {field_name} must be between 0 and 1")

    return result
